class Solution {
public:
    vector<int> rearrangeArray(vector<int>& nums) {
        sort(nums.begin(), nums.end());
        int n = nums.size();
        vector<int> ans(n);
        int idx = 0;
        for (int i = 0; i < n; i += 2) ans[i] = nums[idx++];
        for (int i = 1; i < n; i += 2) ans[i] = nums[idx++];
        return ans;
    }
};

class Solution {
    public int[] rearrangeArray(int[] nums) {
        java.util.Arrays.sort(nums);
        int n = nums.length;
        int[] ans = new int[n];
        int idx = 0;
        for (int i = 0; i < n; i += 2) ans[i] = nums[idx++];
        for (int i = 1; i < n; i += 2) ans[i] = nums[idx++];
        return ans;
    }
}

